def fa(x):return str(x).translate(str.maketrans('0123456789.,','۰۱۲۳۴۵۶۷۸۹٫٬'))
def pct(n,total=N):return fa(f'{100*n/total:.1f}')+'٪'
def runfmt(r,size=None,bold=False,ltr=False):
    r.font.name='Calibri' if ltr else FONT
    if size:r.font.size=Pt(size)
    r.font.bold=bold
    rp=r._element.get_or_add_rPr()
    xml(rp,'w:rFonts',{'w:ascii':'Calibri' if ltr else FONT,'w:hAnsi':'Calibri' if ltr else FONT,'w:cs':FONT})
    xml(rp,'w:rtl',{'w:val':'0' if ltr else '1'})
    xml(rp,'w:bCs',{'w:val':'1' if bold else '0'})
    if size:xml(rp,'w:szCs',{'w:val':int(size*2)})
    return r
def p(text='',style=None,size=None,bold=False,center=False):
    para=doc.add_paragraph(style=style)
    para.alignment=WD_ALIGN_PARAGRAPH.CENTER if center else WD_ALIGN_PARAGRAPH.LEFT
    xml(para._p.get_or_add_pPr(),'w:bidi')
    for piece in re.split(r'([۰-۹0-9]+(?:/[۰-۹0-9]+)+)',text):
        if piece:runfmt(para.add_run(piece),size,bold or style in ['Title','Heading 1','Heading 2','Heading 3'],bool(re.fullmatch(r'[۰-۹0-9]+(?:/[۰-۹0-9]+)+',piece)))
    if style=='Title':
        borders=xml(para._p.get_or_add_pPr(),'w:pBdr')
        for side in ['top','left','bottom','right','between']:xml(borders,'w:'+side,{'w:val':'nil'})
    return para
def h(text,level=1):return p(text,f'Heading {level}')
def page(title):doc.add_page_break(); h(title)
def link(label,url,para=None):
    para=para or doc.add_paragraph()
    para.alignment=WD_ALIGN_PARAGRAPH.LEFT
    xml(para._p.get_or_add_pPr(),'w:bidi')
    rel=para.part.relate_to(url,RT.HYPERLINK,is_external=True)
    hl=xml(para._p,'w:hyperlink',{'r:id':rel})
    rr=xml(hl,'w:r'); rp=xml(rr,'w:rPr')
    xml(rp,'w:rFonts',{'w:ascii':'Calibri','w:hAnsi':'Calibri','w:cs':FONT})
    xml(rp,'w:color',{'w:val':'155A84'}); xml(rp,'w:sz',{'w:val':'20'});xml(rp,'w:szCs',{'w:val':'22'})
    xml(rp,'w:rtl',{'w:val':'0' if label.startswith('http') else '1'})
    xml(rr,'w:t').text=label
    return para
def table(headers,rows,widths=None,size=11.5):
    t=doc.add_table(rows=1,cols=len(headers));t.alignment=WD_TABLE_ALIGNMENT.CENTER;t.autofit=False
    pr=t._tbl.tblPr; xml(pr,'w:bidiVisual')
    borders=xml(pr,'w:tblBorders')
    for side in ['top','left','bottom','right','insideH','insideV']:xml(borders,'w:'+side,{'w:val':'single','w:sz':'4','w:color':'D9D9D9'})
    margins=xml(pr,'w:tblCellMar')
    for side in ['top','bottom']:xml(margins,'w:'+side,{'w:w':'45','w:type':'dxa'})
    for side in ['left','right']:xml(margins,'w:'+side,{'w:w':'110','w:type':'dxa'})
    if widths is None:widths=[17.4/len(headers)]*len(headers)
    for c,w in zip(t.columns,widths):c.width=Cm(w)
    for idx,vals in enumerate([headers]+list(rows)):
        cells=t.rows[0].cells if idx==0 else t.add_row().cells
        trpr=t.rows[idx]._tr.get_or_add_trPr();xml(trpr,'w:cantSplit')
        if idx==0:xml(trpr,'w:tblHeader')
        for j,(cell,val) in enumerate(zip(cells,vals)):
            cell.width=Cm(widths[j]);cell.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
            if idx==0:xml(cell._tc.get_or_add_tcPr(),'w:shd',{'w:fill':'DCEAF3'})
            elif idx%2==0:xml(cell._tc.get_or_add_tcPr(),'w:shd',{'w:fill':'F6F8FA'})
            q=cell.paragraphs[0];q.alignment=WD_ALIGN_PARAGRAPH.LEFT if j==0 or len(str(val))>22 else WD_ALIGN_PARAGRAPH.CENTER
            q.paragraph_format.space_after=Pt(1);q.paragraph_format.space_before=Pt(1);q.paragraph_format.line_spacing=1.05
            xml(q._p.get_or_add_pPr(),'w:bidi');runfmt(q.add_run(str(val)),size,idx==0)
    gap=doc.add_paragraph();gap.paragraph_format.space_after=Pt(3);gap.paragraph_format.line_spacing=Pt(2)
    runfmt(gap.add_run(''),2)
    return t
def figure(name,caption,width=17.3):
    q=doc.add_paragraph();q.alignment=WD_ALIGN_PARAGRAPH.CENTER;q.paragraph_format.keep_with_next=True
    rr=q.add_run();rr.add_picture(str(OUT/name),width=Cm(width))
    for el in rr._r.xpath('.//wp:docPr'):el.set('descr',caption)
    p(caption,'Caption')
    link(URL,URL)
def cite(ids):
    q=p('منابع قابل پیگیری در بانک  ',size=10.5)
    for sid in ids:
        src=next(x for x in D['sources'] if x['Source_ID']==sid)
        link(sid+'  ',src['URL'],q)
    return q

